        if self.progressDialog:
            self.progressDialog.close()
            self.progressDialog = None

        data: List[Dict[str, Any]]
        if isinstance(event, ResultEvent):
            data = event.data
        else:
            data = event
            
        if data:
            self.statusbar.showMessage(f"Read {len(data)} logs")
            self.data = data
            self.data_view = self.data
            self.SetupGrid()

